// Dos programas que suman el peso de la zona Sur (datos inventados)
let total = 0;
function sumarImpura(pesos) {
  for (const kg of pesos) total += kg;   // toca una variable de afuera
  return total;
}
const sumarPura = (pesos) => pesos.reduce((acc, kg) => acc + kg, 0);

