// encadenar: aplica las funciones de izquierda a derecha
const encadenar = (...fs) => (x) => fs.reduce((acc, f) => f(acc), x);
// componer: de derecha a izquierda, como en matemática (f ∘ g)(x) = f(g(x))
const componer = (...fs) => (x) => fs.reduceRight((acc, f) => f(acc), x);

