// Clausura con estado: «cuenta» solo existe adentro, nadie de afuera la toca
function crearContadorDeBultos() {
  let cuenta = 0;
  return {
    sumar: (n) => { cuenta += n; return cuenta; },
    ver: () => cuenta,
  };
}
const turnoMañana = crearContadorDeBultos();
const turnoTarde = crearContadorDeBultos();
turnoMañana.sumar(10);
turnoMañana.sumar(5);
turnoTarde.sumar(2);
console.log(turnoMañana.ver(), turnoTarde.ver());   // 15 2: cada llamada creó su propia «cuenta»
console.log(typeof cuenta);                          // undefined: afuera no existe

// Clausura pura: recuerda un dato que no cambia
const conRecargo = (porcentaje) => (precio) => precio * (1 + porcentaje / 100);
const iva = conRecargo(21);
const flete = conRecargo(8);
console.log(iva(1000), flete(1000));                 // 1210 1080

// Una clausura recuerda la VARIABLE, no el valor que tenía: con var hay una sola `i` para todo el bucle
const conVar = [];
for (var i = 0; i < 3; i++) conVar.push(() => i);
console.log(conVar.map((f) => f()));                 // [ 3, 3, 3 ]
const conLet = [];
for (let j = 0; j < 3; j++) conLet.push(() => j);    // con let, cada vuelta tiene su propia `j`
console.log(conLet.map((f) => f()));                 // [ 0, 1, 2 ]

// Impura: depende del reloj. La misma llamada da cosas distintas según cuándo la hagas.
const estaDemoradoImpura = (envio) => Date.now() - envio.promesa > 24 * 3600 * 1000;

// Pura: el «ahora» entra como argumento
const estaDemorado = (envio, ahora) => ahora - envio.promesa > 24 * 3600 * 1000;

const envio = { id: "E-102", kg: 8.5, promesa: Date.UTC(2026, 10, 12, 9, 0) };  // promesa: 12-nov-2026, 09:00 UTC

console.log(estaDemorado(envio, Date.UTC(2026, 10, 13, 8, 0)));    // false: pasaron 23 horas
console.log(estaDemorado(envio, Date.UTC(2026, 10, 13, 10, 0)));   // true: pasaron 25 horas
console.log(estaDemorado(envio, Date.UTC(2026, 10, 13, 10, 0)));   // true: siempre lo mismo

// Núcleo puro: decide y devuelve un resumen, no imprime nada
const resumen = (envios, ahora) => {
  const demorados = envios.filter((e) => estaDemorado(e, ahora));
  return { demorados: demorados.length, kg: demorados.reduce((s, e) => s + e.kg, 0) };
};

// Cáscara con efectos: acá (y solo acá) se lee el reloj y se imprime
const envios = [envio, { id: "E-104", kg: 3, promesa: Date.UTC(2026, 10, 13, 9, 0) }];
console.log(resumen(envios, Date.UTC(2026, 10, 13, 10, 0)));
